  LT.places.DOMINION_ALLEYS_CANAL_CROSSING = {"id": "DOMINION_ALLEYS_CANAL_CROSSING", "name": "Canal Crossing", "description": "These alleyway crossings over the city's canal are considered to be very dangerous, and have the reputation as being the favourite haunts of dangerous desperadoes.", "svg": "dominion/bridge", "colourName": "BASE_BLUE_LIGHT", "backgroundName": "MAP_BACKGROUND"};
  LT.places.DOMINION_AUNTS_HOME = {"id": "DOMINION_AUNTS_HOME", "name": "Lilaya's Home", "description": "Lilaya's home is more of a mansion than a town house, and, due to its impressive size, stands out as a particularly impressive building in this area.", "svg": "dominion/homeIcon", "colourName": "BASE_BLUE_LIGHT", "backgroundName": "MAP_BACKGROUND"};
