  LT.places.DOMINION_BANK = {"id": "DOMINION_BANK", "name": "Bank of Dominion", "description": "The Realm's only bank, the 'Bank of Dominion' has its main branch here in Dominion.", "svg": "dominion/bankIcon", "colourName": "BASE_GOLD", "backgroundName": "MAP_BACKGROUND"};
  LT.places.DOMINION_BOULEVARD = {"id": "DOMINION_BOULEVARD", "name": "Dominion Boulevard", "description": "The main boulevards which lead to the centre of Dominion are extremely wide and well-travelled, and are very regularly patrolled by Enforcers.", "svg": null, "colourName": "BASE_PINK_LIGHT", "backgroundName": "MAP_BACKGROUND_PINK"};
  LT.places.DOMINION_CALLIE_BAKERY = {"id": "DOMINION_CALLIE_BAKERY", "name": "The Creamy Bakey", "description": "This bakery is owned by a horse-girl named Callie.", "svg": "dominion/callieBakeryIcon", "colourName": "BASE_BROWN", "backgroundName": "MAP_BACKGROUND"};
  LT.places.DOMINION_CANAL = {"id": "DOMINION_CANAL", "name": "Canal", "description": "Dominion's canal is safe enough for anyone on a barge or boat, but for those walking along the often-deserted and Enforcer-free towpaths, it's a different story entirely...", "svg": "dominion/canalIcon", "colourName": "BASE_BLUE_LIGHT", "backgroundName": "MAP_BACKGROUND"};
  LT.places.DOMINION_CANAL_END = {"id": "DOMINION_CANAL_END", "name": "Canal", "description": "The towpaths which run alongside Dominion's canal come to an abrupt end at the city outskirts.", "svg": "dominion/canalEndIcon", "colourName": "BASE_BLUE", "backgroundName": "MAP_BACKGROUND"};
  LT.places.DOMINION_CITY_HALL = {"id": "DOMINION_CITY_HALL", "name": "City hall", "description": "Acting as a centre for regional government, the city hall handles the administrative affairs of not only Dominion, but of all of Lilith's Domain.", "svg": "dominion/townHallIcon", "colourName": "BASE_INDIGO", "backgroundName": "MAP_BACKGROUND"};
  LT.places.DOMINION_DARK_ALLEYS = {"id": "DOMINION_DARK_ALLEYS", "name": "Dark Alleyways", "description": "The darkest depths of Dominion's twisting, maze-like alleyways are avoided even by the muggers who would usually call such places home...", "svg": "dominion/alleysDarkIcon", "colourName": "BASE_PURPLE", "backgroundName": "MAP_BACKGROUND"};
